<?php
declare(strict_types=1);
require_once '../includes/admin-auth.php';
require_once '../config/database.php';
require_once '../includes/admin-helper.php';
require_once '../includes/premium-admin-helper.php';
require_once '../includes/branch-context.php';

$pageTitle='Staff';
$flash=premiumAdminGetFlash();
$branchId=requireAssignedBranch($pdo);
$branchLabel=branchName($pdo,$branchId);

if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!premiumAdminVerifyCsrf($_POST['csrf_token']??null))premiumAdminFlash('error','Session token expired.','staff.php');
 $id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');
 if($action==='toggle'&&$id){$pdo->prepare("UPDATE users SET status=CASE WHEN status='active' THEN 'inactive' ELSE 'active' END WHERE id=? AND role='staff' AND branch_id=?")->execute([$id,$branchId]);premiumAdminFlash('success','Staff status updated.','staff.php');}
 if($action==='delete'&&$id){
  try{$pdo->beginTransaction();$pdo->prepare("DELETE FROM staff_profiles WHERE user_id=?")->execute([$id]);$pdo->prepare("DELETE FROM users WHERE id=? AND role='staff' AND branch_id=?")->execute([$id,$branchId]);$pdo->commit();premiumAdminFlash('success','Staff account deleted.','staff.php');}
  catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();premiumAdminFlash('error','This staff account is connected to existing records and cannot be deleted. Deactivate it instead.','staff.php');}
 }
 if($action==='save'){
  $fullname=trim((string)($_POST['fullname']??''));$email=strtolower(trim((string)($_POST['email']??'')));$phone=trim((string)($_POST['phone_number']??''));$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$specialty=trim((string)($_POST['specialty']??''));$employment=(string)($_POST['employment_status']??'full_time');$accountStatus=(string)($_POST['status']??'active');
  if($fullname===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$username==='')premiumAdminFlash('error','Complete the required staff details.','staff.php');
  if(!in_array($employment,['full_time','part_time','contractual'],true)||!in_array($accountStatus,['active','inactive'],true))premiumAdminFlash('error','Choose valid staff and account statuses.','staff.php');
  try{$pdo->beginTransaction();if(strlen($password)<8)throw new RuntimeException('New staff password must have at least 8 characters.');$pdo->prepare("INSERT INTO users(fullname,username,email,phone_number,password,role,status,branch_id) VALUES(?,?,?,?,?,'staff',?,?)")->execute([$fullname,$username,$email,$phone?:null,password_hash($password,PASSWORD_DEFAULT),$accountStatus,$branchId]);$id=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO staff_profiles(user_id,specialty,branch,employment_status) VALUES(?,?,?,?)")->execute([$id,$specialty?:null,$branchLabel,$employment]);$pdo->commit();premiumAdminFlash('success','Staff account created.','staff.php');}
  catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();premiumAdminFlash('error',$e instanceof RuntimeException?$e->getMessage():'Staff details could not be saved. Check the username and email.','staff.php');}
 }
}

$search=trim((string)($_GET['search']??''));$status=trim((string)($_GET['status']??''));$specialty=trim((string)($_GET['specialty']??''));
$where=["u.role='staff'","u.branch_id=:branch_scope"];$params=['branch_scope'=>$branchId];
if($search!==''){$where[]="(u.fullname LIKE :n OR u.email LIKE :e OR u.username LIKE :u OR u.phone_number LIKE :p)";$v='%'.$search.'%';$params+=['n'=>$v,'e'=>$v,'u'=>$v,'p'=>$v];}
if(in_array($status,['active','inactive'],true)){$where[]='u.status=:status';$params['status']=$status;}
if($specialty!==''){$where[]='sp.specialty=:specialty';$params['specialty']=$specialty;}
$stmt=$pdo->prepare("SELECT u.id,u.fullname,u.username,u.email,u.phone_number,u.status,sp.specialty,sp.branch,sp.employment_status FROM users u LEFT JOIN staff_profiles sp ON sp.user_id=u.id WHERE ".implode(' AND ',$where)." ORDER BY u.fullname");
premiumAdminBind($stmt,$params);$stmt->execute();$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);
$specStmt=$pdo->prepare("SELECT DISTINCT sp.specialty FROM staff_profiles sp JOIN users u ON u.id=sp.user_id WHERE u.role='staff' AND u.branch_id=? AND sp.specialty IS NOT NULL AND sp.specialty<>'' ORDER BY sp.specialty");$specStmt->execute([$branchId]);$specialties=$specStmt->fetchAll(PDO::FETCH_COLUMN);
include '../includes/admin-header.php';
?>
<link rel="stylesheet" href="../assets/css/premium-admin-suite.css">
<link rel="stylesheet" href="../assets/css/staff-management.css">
<div class="admin-layout"><?php include '../includes/admin-sidebar.php';?><main class="admin-content">
<header class="admin-page-header premium-admin-header"><div><p class="premium-admin-kicker">Team management</p><h1>Staff</h1><p>Manage staff accounts, employment details, activity, and access status.</p></div><div class="premium-admin-row-actions"><a class="admin-btn admin-btn-light" href="staff-schedule.php">Manage Schedules</a><button class="admin-btn admin-btn-primary" data-premium-modal-open="staffModal">+ Add Staff</button></div></header>
<?php if($flash):?><div class="premium-admin-alert <?=htmlspecialchars($flash['type'])?>"><?=htmlspecialchars($flash['message'])?></div><?php endif;?>
<section class="admin-card staff-filter-card"><div class="staff-section-title"><h2>Search &amp; Filter</h2><p>Find staff by name, contact information, status, or specialty.</p></div><form class="staff-filter-form" method="GET"><div class="filter-field"><label for="search">Search</label><input id="search" name="search" value="<?=htmlspecialchars($search)?>" placeholder="Name, username, email, or phone"></div><div class="filter-field"><label for="status">Account Status</label><select id="status" name="status"><option value="">All status</option><option value="active" <?=$status==='active'?'selected':''?>>Active</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>Inactive</option></select></div><div class="filter-field"><label for="specialty">Specialty</label><select id="specialty" name="specialty"><option value="">All specialties</option><?php foreach($specialties as $option):?><option value="<?=htmlspecialchars((string)$option)?>" <?=$specialty===$option?'selected':''?>><?=htmlspecialchars((string)$option)?></option><?php endforeach;?></select></div><div class="staff-filter-actions"><button class="btn btn-gold">Filter</button><a class="btn btn-light" href="staff.php">Reset</a></div></form></section>
<section class="admin-card staff-table-card"><div class="staff-table-heading"><h2>Registered Staff</h2><p><?=count($rows)?> staff record(s) found.</p></div><div class="table-wrap"><table class="staff-table"><thead><tr><th>Staff Member</th><th>Contact</th><th>Specialty</th><th>Employment</th><th>Account</th><th>Actions</th></tr></thead><tbody>
<?php if(!$rows):?><tr><td colspan="6" class="empty-state">No staff accounts found.</td></tr><?php else:foreach($rows as $row):?><tr><td><div class="staff-name-cell"><strong><?=htmlspecialchars($row['fullname'])?></strong><span>@<?=htmlspecialchars($row['username'])?></span></div></td><td><div class="staff-contact-cell"><span><?=htmlspecialchars($row['email']??'—')?></span><small><?=htmlspecialchars($row['phone_number']??'No phone number')?></small></div></td><td><span class="staff-specialty-badge"><?=htmlspecialchars($row['specialty']??'Unassigned')?></span></td><td><span class="staff-employment-badge"><?=htmlspecialchars(ucfirst(str_replace('_',' ',$row['employment_status']??'full_time')))?></span></td><td><span class="badge badge-<?=$row['status']==='active'?'success':'inactive'?>"><?=ucfirst($row['status'])?></span></td><td><div class="staff-action-group"><a class="staff-action-btn staff-action-edit" href="edit-staff.php?id=<?=(int)$row['id']?>">Edit</a><form method="POST"><input type="hidden" name="csrf_token" value="<?=premiumAdminCsrf()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="staff-action-btn staff-action-status"><?=$row['status']==='active'?'Deactivate':'Activate'?></button></form><form method="POST" onsubmit="return confirm('Delete this staff account?');"><input type="hidden" name="csrf_token" value="<?=premiumAdminCsrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="staff-action-btn staff-action-delete">Delete</button></form></div></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<?php include '../includes/admin-footer.php';?></main></div>
<div class="premium-admin-modal" id="staffModal"><div class="premium-admin-modal-backdrop" data-premium-modal-close></div><section class="premium-admin-modal-dialog"><header><div><p class="premium-admin-kicker">Staff account</p><h2>Add Staff</h2></div><button type="button" class="premium-admin-modal-close" data-premium-modal-close aria-label="Close">&#215;</button></header><form method="POST"><input type="hidden" name="csrf_token" value="<?=premiumAdminCsrf()?>"><input type="hidden" name="action" value="save"><div class="premium-admin-form-grid"><div class="admin-field premium-admin-span-2"><label>Full name</label><input name="fullname" required></div><div class="admin-field"><label>Username</label><input name="username" required></div><div class="admin-field"><label>Email</label><input name="email" type="email" required></div><div class="admin-field"><label>Phone number</label><input name="phone_number"></div><div class="admin-field"><label>Specialty</label><input name="specialty" placeholder="e.g. Nail technician"></div><div class="admin-field"><label>Employment status</label><select name="employment_status"><option value="full_time">Full Time</option><option value="part_time">Part Time</option><option value="contractual">Contractual</option></select></div><div class="admin-field"><label>Account status</label><select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></div><div class="admin-field"><label>Password</label><input name="password" type="password" minlength="8" required></div></div><div class="premium-admin-modal-actions"><button type="button" class="admin-btn admin-btn-light" data-premium-modal-close>Cancel</button><button class="admin-btn admin-btn-primary">Create Staff</button></div></form></section></div>
